begin; alter table public.wall_names add column background_style text not null default 'plain' check(background_style in ('plain','cork','paper','dots')), add column frame_style text not null default 'classic' check(frame_style in ('classic','cream','wood','pastel','neon')); grant insert(background_style,frame_style),update(background_style,frame_style) on public.wall_names to authenticated; commit;